// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length <= 50);
        Reverter reverter = new Reverter();
        bool ok;
        try c.transfer(from, address(reverter), _tos, v) returns (bool ret) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Reference C should revert when a sub-call reverts");
    }
}

contract Reverter {
    fallback() external payable {
        revert("always fails");
    }
}
